SELECT 
FROM violation_log
WHERE violation_type = #{violationType}

    AND created_at >= #{startTime}


    AND created_at <= #{endTime}

ORDER BY created_at DESC

SELECT 
FROM violation_log
WHERE consumer = #{consumer}

    AND created_at >= #{startTime}


    AND created_at <= #{endTime}

ORDER BY created_at DESC

mapper.update:
UPDATE violation_log
SET feedback_status = #{feedbackStatus, jdbcType=VARCHAR}
WHERE violation_id = #{violationId, jdbcType=VARCHAR}

mapper.select:
SELECT COUNT(*)
FROM violation_log
WHERE created_at >= #{startTime}
  AND created_at <= #{endTime}

SELECT violation_type, COUNT(*) as count
FROM violation_log
WHERE created_at >= #{startTime}
  AND created_at <= #{endTime}
GROUP BY violation_type
ORDER BY count DESC

SELECT risk_level, COUNT(*) as count
FROM violation_log
WHERE created_at >= #{startTime}
  AND created_at <= #{endTime}
GROUP BY risk_level
ORDER BY count DESC
